// Chess capture. Keep it on the board — globalEvents works in object scripts.
// Grid-based: the pieces' convex-hull colliders make overlap detection impossible.

const PITCH = 0.174;              // measured square pitch on this board
const CAPTURE_ZONE_NAME = "CaptureZone";

/** Scene seats are colour ids; the nameplates are just labels. Black sits at red, White at blue. */
const SEAT_BY_SIDE: Record<string, string> = { white: "blue", black: "red" };

/*world.addObjectMenuItem({
  id: "promote-queen",
  label: "Promote to Queen",
  match: { tags: ["pawn"] }          // omit `match` for every entity
});

globalEvents.onObjectMenuItem.add((object, itemId, context) => {
  if (itemId !== "promote-queen") return;
  world.broadcast(`${context.actor} promotes ${object.name}.`);
});*/

world.log("[chess] capture script loaded");   // proves the script runs at all

const takenBy = new Map<string, number>();

globalEvents.onObjectDropped.add((mover) => {
  void resolveCapture(mover);
});

async function resolveCapture(mover: ObjectHandle): Promise<void> {
  if (!mover.tags.includes("piece")) return;
  const attacker = sideOf(mover);
  if (!attacker) return;

  // ⚠ NO settle wait. `mover.position` is the handle's snapshot from the drop event — the
  // position BEFORE the convex hulls shove the two pieces ~0.116 apart (two thirds of a
  // square). Waiting for the bodies to settle is what makes the capture undetectable.
  const dropPos = mover.position;

  const board = (await world.getAllObjects({ kind: "board" }))[0];
  if (!board) {
    world.log("[chess] no board on the table — cannot resolve squares.");
    return;
  }
  const moverCell = cellOf(dropPos, board.position);

  for (const other of await world.getAllObjects()) {
    if (other.id === mover.id || !other.tags.includes("piece")) continue;
    const side = sideOf(other);
    if (!side || side === attacker) continue;

    const cell = cellOf(other.position, board.position);
    if (cell.col !== moverCell.col || cell.row !== moverCell.row) continue;

    world.log(`[chess] ${attacker} takes ${other.name ?? other.id} at ${cell.col},${cell.row}`);
    // The snap point set the attacker down ON the victim. Take the victim's spot
    // (the square centre, at board height) before moving it out.
    const square = other.position;
    await sendToCaptureZone(other, attacker);
    // Victim out FIRST, then the attacker in. The other order puts two pieces
    // in the same space and physics shoves them apart.
    mover.setPosition([square[0], square[1], square[2]]);
    return;
  }
}

function cellOf(p: Vec3, origin: Vec3): { col: number; row: number } {
  return {
    col: Math.round((p[0] - origin[0]) / PITCH + 3.5),
    row: Math.round((p[2] - origin[2]) / PITCH + 3.5)
  };
}

function sideOf(piece: ObjectData): string | null {
  if (piece.tags.includes("white")) return "white";
  if (piece.tags.includes("black")) return "black";
  return null;
}

async function sendToCaptureZone(victim: ObjectHandle, capturer: string): Promise<void> {
  const seat = SEAT_BY_SIDE[capturer];
  if (!seat) return;

  const index = takenBy.get(capturer) ?? 0;
  takenBy.set(capturer, index + 1);

  const zones = await world.getSeatZones(seat);
  const zone = zones.find((z) => z.name.toLowerCase() === CAPTURE_ZONE_NAME.toLowerCase());
  if (!zone) {
    world.log(`[chess] no "${CAPTURE_ZONE_NAME}" on seat ${seat} (${capturer}).`);
    return;
  }

  // The zone declares arrange: grid, 6x6, gutter 0.05 — so use 6 per row, not 8.
  // 0.8 / 6 = 0.133 per cell, comfortably clear of the ~0.116 piece width. At 8 per row
  // the 0.1 spacing is NARROWER than a piece and they shove each other out of the zone.
  const perRow = 6;
  const stepX = zone.size[0] / perRow;
  const stepZ = zone.size[2] / perRow;

  victim.setPosition([
    zone.position[0] - zone.size[0] / 2 + stepX * (index % perRow) + stepX / 2,
    victim.position[1],   // keep its resting height and let it settle onto the table
    zone.position[2] - zone.size[2] / 2 + stepZ * Math.floor(index / perRow) + stepZ / 2
  ]);

  world.broadcast(`${capturer} captures ${victim.name ?? "a piece"}.`);
}

